function validate([stones]) {
  if (!Array.isArray(stones) || stones.length < 1 || stones.length > 100000) return 'stones needs 1 to 100000 values.';
  if (stones.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each stone value is an integer from 1 to 10000.';
  return null;
}

