function stoneGameIX(stones) {
  const n = stones.length;
  const full = (1 << n) - 1;
  const memo = new Map();
  // moverWins(mask, sum): does the player about to move win, given the taken stones and their total mod 3?
  const moverWins = (mask, sum) => {
    if (mask === full) return n % 2 === 1; // no stones left: Bob wins, and Bob moves next exactly when n is odd
    if (memo.has(mask)) return memo.get(mask);
    let result = false;
    for (let i = 0; i < n && !result; i++) {
      if (mask & (1 << i)) continue;
      const next = (sum + stones[i]) % 3;
      if (next === 0) continue; // this move loses on the spot
      if (!moverWins(mask | (1 << i), next)) result = true;
    }
    memo.set(mask, result);
    return result;
  };
  return moverWins(0, 0);
}

