function generate(rand, size) {
  const n = size === 'large' ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 9);
  const max = size === 'large' ? 10000 : 12;
  // Skewed residue weights so that both parities of zeros and lopsided ones/twos counts appear.
  const weights = [rand(), rand(), rand()];
  if (rand() < 0.3) weights[Math.floor(rand() * 3)] = 0;
  if (weights[0] + weights[1] + weights[2] === 0) weights[1] = 1;
  const total = weights[0] + weights[1] + weights[2];
  const stones = [];
  for (let i = 0; i < n; i++) {
    let pick = rand() * total;
    let residue = 0;
    while (residue < 2 && pick >= weights[residue]) { pick -= weights[residue]; residue++; }
    if (weights[residue] === 0) residue = weights.findIndex(w => w > 0);
    const lo = residue === 0 ? 1 : 0;
    const hi = Math.floor((max - residue) / 3);
    stones.push(residue + 3 * (lo + Math.floor(rand() * (hi - lo + 1))));
  }
  return [stones];
}
